list.definition:
SELECT
    (
        SELECT STRING_AGG(QRCODEID, ',') WITHIN GROUP (ORDER BY Position)
        FROM ServerMap
        WHERE StoreHouseID = ${rack_id}
          AND PalletPosition = 'L'
    )
    +
    (
        SELECT STRING_AGG(QRCODEID, ',') WITHIN GROUP (ORDER BY Position)
        FROM ServerMap
        WHERE StoreHouseID = ${rack_id}
          AND PalletPosition = 'R'
    )
    AS Result;

